import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from './saved-format.ts';
import { MISMATCH_MS } from './game.ts';
import { SelectionKind, type Selection } from './selection.ts';
import type { GameState } from './game.ts';

export function readSelection(
  value: unknown,
  state: GameState,
  matched: readonly number[],
): Selection | null {
  if (!isJsonObject(value)) return null;
  const available = (index: unknown): index is number =>
    isNonnegativeSafeInteger(index) && index < state.deck.length && !matched.includes(index);
  switch (value.kind) {
    case SelectionKind.closed:
      return hasExactKeys(value, ['kind']) ? { kind: SelectionKind.closed } : null;
    case SelectionKind.one:
      return hasExactKeys(value, ['kind', 'index']) && available(value.index)
        ? { kind: SelectionKind.one, index: value.index }
        : null;
    case SelectionKind.mismatch:
      if (!hasExactKeys(value, ['kind', 'first', 'second', 'remainingMs'])) return null;
      if (!available(value.first) || !available(value.second) || value.first === value.second)
        return null;
      if (state.deck[value.first] === state.deck[value.second]) return null;
      if (
        !isNonnegativeSafeInteger(value.remainingMs) ||
        value.remainingMs < 1 ||
        value.remainingMs > MISMATCH_MS
      )
        return null;
      return {
        kind: SelectionKind.mismatch,
        first: value.first,
        second: value.second,
        remainingMs: value.remainingMs,
      };
    default:
      return null;
  }
}

export function readMatched(value: unknown, state: GameState): readonly number[] | null {
  if (!Array.isArray(value)) return null;
  const matched: number[] = [];
  const counts = new Map<number, number>();
  for (const index of value) {
    if (!isNonnegativeSafeInteger(index) || index >= state.deck.length || matched.includes(index))
      return null;
    const face = state.deck[index];
    if (face === undefined) return null;
    matched.push(index);
    counts.set(face, (counts.get(face) ?? 0) + 1);
  }
  return [...counts.values()].every((count) => count === 2) ? matched : null;
}
import assert from 'node:assert/strict';
import { test } from 'vitest';
import { activateCard, advanceGame, createGame, MISMATCH_MS, MOVES_MAX } from './game.ts';
import {
  decodeSnapshot,
  encodeSnapshot,
  SNAPSHOT_KEYS,
  SNAPSHOT_MAX_BYTES,
  SNAPSHOT_VERSION,
} from './snapshot.ts';
import { SelectionKind } from './selection.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS, SPEC_VECTOR } from './game.fixture.ts';

function snapshot(overrides: Record<string, unknown> = {}): string {
  return JSON.stringify({
    version: SNAPSHOT_VERSION,
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
    ...overrides,
  });
}

test('snapshot round trips preserve pending time and serialize only the declared fields', () => {
  const state = advanceGame(activateCard(activateCard(createGame(EXAMPLE_CODE), 0), 1), 175);
  assert.deepEqual(decodeSnapshot(encodeSnapshot(state)), state);
  assert.deepEqual(state.selection, {
    kind: SelectionKind.mismatch,
    first: 0,
    second: 1,
    remainingMs: MISMATCH_MS - 175,
  });
  assert.equal(SNAPSHOT_VERSION, SPEC_VECTOR.snapshotVersion);
  assert.equal(SNAPSHOT_MAX_BYTES, SPEC_VECTOR.snapshotBytes);
  const exported: unknown = JSON.parse(encodeSnapshot(state));
  assert.ok(exported && typeof exported === 'object');
  assert.deepEqual(Object.keys(exported).sort(), [...SNAPSHOT_KEYS].sort());
});

test('snapshots accept whole pairs and completed states without changing the source order', () => {
  const state = activateCard(activateCard(createGame(EXAMPLE_CODE), 6), 2);
  assert.deepEqual(decodeSnapshot(encodeSnapshot(state))?.matched, [2, 6]);
  assert.deepEqual(state.matched, [6, 2]);
  assert.equal(
    decodeSnapshot(
      snapshot({ matched: EXAMPLE_PAIRS.flat(), moves: EXAMPLE_PAIRS.length, started: true }),
    )?.matched.length,
    16,
  );
  assert.ok(decodeSnapshot(snapshot({ moves: 17, started: true })));
});

